def orbit(r,c):
    pairs={(r,c)}
    changed=True
    while changed:
        old=len(pairs)
        for x,y in list(pairs):
            if x>=2: pairs.add((31-x,y))
            if y>=2: pairs.add((x,31-y))
            pairs.add((y,x))
        changed=len(pairs)>old
    return sorted(pairs)
